import math

WITNESS = {
    "perfect_power_examples": [(144, 12, 2), (705600, 840, 2)],
    "k4_nonexistence_bound": 1000000,
}

def _is_perfect_power(n):
    if n < 4:
        return False
    b = 2
    while b * b <= n:
        p = b * b
        while p <= n:
            if p == n:
                return True
            p *= b
        b += 1
    return False

def verify():
    # Part 1: exact perfect-power witnesses (fail closed on any mismatch)
    for (n, b, e) in WITNESS["perfect_power_examples"]:
        p = 1
        for _ in range(e):
            p *= b
        if p != n:
            return False
        if not _is_perfect_power(n):
            return False
    # Part 2: k=4 nonexistence for t <= 10^6, exact integer arithmetic only
    B = WITNESS["k4_nonexistence_bound"]
    if B > 10**6:
        return False
    for t in range(1, B + 1):
        prod = t * (t + 1) * (t + 2) * (t + 3)
        if _is_perfect_power(prod):
            return False
    return True

RESULT = verify()
